    if (($c.util.getComponent('cal_listSchdlDd').getValue() == null ? '' : String($c.util.getComponent('cal_listSchdlDd').getValue())) === '') {
        await $c.win.alert('상장(희망)일을 입력하십시오');
        return;
    }
    if (is201412(listSchdlDd)) {
        await $c.win.alert('신청 가능한 희망일입니다.');
        $c.util.getComponent('dma_registerReq').set('possibleYn', 'Y');
    } else {
        const url = "/jldfil55300n/jldfil55300n.xml?method=checkListDd&listSchdlDd=" + listSchdlDd + "&bzProcsNo=" + dma_pageContext.get("bzProcsNo") + "";
