        await $c.win.alert('업종을  입력 하십시오');
        $c.util.getComponent('ipt_stdIndCd').select();
        return;
    }
    if (($c.util.getComponent('cal_foundDd').getValue() == null ? '' : String($c.util.getComponent('cal_foundDd').getValue())) === '') {
        await $c.win.alert('설립일을  입력 하십시오');
        $c.util.getComponent('cal_foundDd').select();
        return;
    }
    if (!scwin.checkMktType()) {
        await $c.win.alert('입력한 이전시장 정보가 상장하려는 시장 정보와 같습니다.\n상장시장이 변경되는 경우, 현재 상장시장을 입력해주세요.\nex) 코넥스 → 코스닥  (코넥스 입력)\n     코스닥 → 유가     (코스닥 입력)');
        return;
    }
    if (!await scwin.checkOldMktType()) {
        return;
    }
    if ($c.util.getComponent('slc_spotIsuTrdMktTpCd').getValue() === '') {
        await $c.win.alert('시장구분을 입력하십시오');
        $c.util.getComponent("slc_spotIsuTrdMktTpCd").focus();
        return;
    }
    if (!await scwin.checkCorpRegNo()) {
        return;
    }
    if (!await scwin.checkBzRegNo()) {
        return;
    }
    if (($c.util.getComponent('cal_listSchdlDd').getValue() == null ? '' : String($c.util.getComponent('cal_listSchdlDd').getValue())) === '') {
        await $c.win.alert('상장(희망)일을 입력하여 주십시오');
        return;
    } else {
        if (($c.util.getComponent('cal_listSchdlDd').getValue() == null ? '' : String($c.util.getComponent('cal_listSchdlDd').getValue())) !== '') {
            if ($c.util.getComponent('dma_registerReq').get('possibleYn') !== 'Y') {
                await $c.win.alert('상장(희망)일 중복체크를 하여 주십시오');
                return;
            }
        }
    }
    if ($c.util.getComponent('ipt_hpage').getValue().toLowerCase().indexOf("://") > -1) {
        await $c.win.alert("'http://'를 제외한 홈페이지를 입력하세요.");
        $c.util.getComponent("ipt_hpage").focus();
        return;
    }
    const selObj = $c.util.getComponent('slc_listInvstgCondTpCd');
    const listClssCdObj = $c.util.getComponent('slc_listClssCd');
    const spacYnChk = $('input:radio[name="spacYn"]:checked').val();
    if (spacYnChk === "Y") {
        if (selObj.getValue() !== "") {
            await $c.win.alert("[코스닥관련-상장심사요건] 항목은 '해당없음'으로 선택됩니다.");
            selObj.options[1].selected = "true";
        }
    } else {
        if (("" + dma_basicComInfo.get("listTpClssCd") + "" !== "06" && "" + dma_basicComInfo.get("listTpClssCd") + "" !== "02" && listClssCdObj.getValue() === "10") || "" + dma_basicComInfo.get("listTpClssCd") + "" === "06" || "" + dma_basicComInfo.get("listTpClssCd") + "" === "07") {
            if (selObj.getValue() === "") {
                await $c.win.alert("[코스닥관련-상장심사요건]은 반드시 '해당없음'이 아닌 값으로 선택하세요.");
                selObj.focus();
                return;
            }
        } else {
            if (selObj.getValue() !== "") {
                await $c.win.alert("[코스닥관련-상장심사요건] 항목은 '해당없음'으로 선택됩니다.");
                selObj.options[1].selected = "true";
            }
        }
    }
    const checkVal = $('input:radio[name="spacYn"]:checked').val();
    if (checkVal === 'Y') {
        if (($c.util.getComponent('cal_exstStrtDd').getValue() == null ? '' : String($c.util.getComponent('cal_exstStrtDd').getValue())) === '') {
            await $c.win.alert('SPAC인 경우 SPAC 존립기간 시작일을 입력하여 주십시오');
            $c.util.getComponent("cal_exstStrtDd").focus();
            return;
        }
        if (($c.util.getComponent('cal_exstEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_exstEndDd').getValue())) === '') {
            await $c.win.alert('SPAC인 경우 SPAC 존립기간 종료일을 입력하여 주십시오');
            $c.util.getComponent("cal_exstEndDd").focus();
            return;
        }
        if (($c.util.getComponent('txa_exstDeadlineRemk').getValue() == null ? '' : String($c.util.getComponent('txa_exstDeadlineRemk').getValue())) === '') {
            await $c.win.alert('SPAC인 경우 SPAC 존립기간 비고를 입력하여 주십시오');
            $c.util.getComponent("txa_exstDeadlineRemk").focus();
            return;
        }
    }
    if ($c.util.getComponent("estiPrfmDiv").getStyle('display') === "block") {
        if (($c.util.getComponent('slc_fsAcntTpCd').getValue() == null ? '' : String($c.util.getComponent('slc_fsAcntTpCd').getValue())) === '') {
            await $c.win.alert('기술성장기업 추정실적의 재무제표계정구분을 선택하세요.');
            $c.util.getComponent("slc_fsAcntTpCd").focus();
            return;
        }
        const checkArr = new Array(0, 1, 4);
        const checkNmArr = $c.util.getComponent('ipt_fsAcntNm');
        const checkObjNmArr = new Array("listYy2agAmt", "listYy1agAmt", "listYyAmt", "listYy1afAmt", "listYy2afAmt");
        let cnt;
        let checkObj;
        for (let i = 0; i < checkObjNmArr.length; i++) {
            checkObj = checkObjNmArr[i];
            for (let j = 0; j < checkArr.length; j++) {
                cnt = checkArr[j];
                if ($c.util.getComponent(checkObj)[cnt].value === '') {
                    await $c.win.alert(checkNmArr[cnt].value + ' 중 필수 입력 항목입니다.');
                    $c.util.getComponent(checkObj)[cnt].select();
                    return;
                }
            }
        }
    }
    if (!await $c.win.confirm("저장 하시겠습니까?")) {
        return;
    }
    const process = $c.util.getComponent('dma_registerReq').get('process');
    const listProcsSeq = $c.util.getComponent('dma_registerReq').get('listProcsSeq');
    if (process === '2' && listProcsSeq === '') {
        $c.util.getComponent('dma_registerReq').set('listProcsSeq', "1");
        if (($c.util.getComponent('ipt_isurCd').getValue() == null ? '' : String($c.util.getComponent('ipt_isurCd').getValue())) === '') {
            $c.util.getComponent("ipt_isurCd").setValue($c.util.getComponent('ipt_isurCd').getValue());
        }
        if ($c.util.getComponent('dma_registerReq').get('pubofrSchdlDd') === '') {
            $c.util.getComponent('dma_registerReq').set('pubofrSchdlDd', "X");
        }
    }
    if ($c.util.getComponent('dma_registerReq').get('listProcsSeq') === '1') {
        $c.util.getComponent('dma_registerReq').set('method', "insertNewListApplContn");
    } else {
        if ($c.util.getComponent('dma_registerReq').get('listProcsSeq') === '2') {
            $c.util.getComponent('dma_registerReq').set('method', "updateNewListApplContn");
        }
    }
    $c.util.getComponent('slc_listClssCd').setDisabled(false);
    $c.util.getComponent('slc_spotIsuTrdMktTpCd').setDisabled(false);
    frm.action = "newListApplContn.do";
    frm.target = "_self";
    await scwin.tx_fn_register();
    /* sdd-asis-lifecycle:end */
};


