/**
 * @method
 * @name scwin.checkBzRegNo
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkBzRegNo = async function () {
    /* sdd-asis-lifecycle:begin fn_checkBzRegNo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let bzRegNo1 = $c.util.getComponent('ipt_bzRegNo1').getValue(); if (bzRegNo1 == null) { bzRegNo1 = ''; }
    let bzRegNo2 = $c.util.getComponent('ipt_bzRegNo2').getValue(); if (bzRegNo2 == null) { bzRegNo2 = ''; }
    let bzRegNo3 = $c.util.getComponent('ipt_bzRegNo3').getValue(); if (bzRegNo3 == null) { bzRegNo3 = ''; }
    if (bzRegNo1 === '') {
        await $c.win.alert('사업자등록번호가 입력되지 않았습니다');
        $c.util.getComponent('ipt_bzRegNo1').select();
        return false;
    }
    if (bzRegNo2 === '') {
        await $c.win.alert('사업자등록번호가 입력되지 않았습니다');
        $c.util.getComponent('ipt_bzRegNo2').select();
        return false;
    }
    if (bzRegNo3 === '') {
        await $c.win.alert('사업자등록번호가 입력되지 않았습니다');
        $c.util.getComponent('ipt_bzRegNo3').select();
        return false;
    }
    const bzRegNo = bzRegNo1 + bzRegNo2 + bzRegNo3;
    if (bzRegNo.length != 10) {
        await $c.win.alert("사업자등록번호가 잘못되었습니다.");
        return false;
    }
    let subMode = 0;
    subMode += parseInt(bzRegNo.substring(0, 1));
    subMode += parseInt(bzRegNo.substring(1, 2)) * 3 % 10;
    subMode += parseInt(bzRegNo.substring(2, 3)) * 7 % 10;
    subMode += parseInt(bzRegNo.substring(3, 4)) * 1 % 10;
    subMode += parseInt(bzRegNo.substring(4, 5)) * 3 % 10;
    subMode += parseInt(bzRegNo.substring(5, 6)) * 7 % 10;
    subMode += parseInt(bzRegNo.substring(6, 7)) * 1 % 10;
    subMode += parseInt(bzRegNo.substring(7, 8)) * 3 % 10;
    subMode += Math.floor(parseInt(bzRegNo.substring(8, 9)) * 5 / 10);
    subMode += parseInt(bzRegNo.substring(8, 9)) * 5 % 10;
    subMode += parseInt(bzRegNo.substring(9, 10));
    if (subMode % 10 != 0) {
        await $c.win.alert("사업자등록번호가 잘못되었습니다.");
        return false;
    }
    $c.util.getComponent('dma_registerReq').set('bzRegNo', bzRegNo);
    return true;
    /* sdd-asis-lifecycle:end */
};


